cssCode:
.chakra-orb {
  position: absolute; width: 40px; height: 40px;
  border-radius: 50%; filter: blur(10px);
  animation: riseChakra 6s infinite ease-in; opacity: 0;
}
@keyframes riseChakra {
  0% { transform: translateY(100px) scale(0.5); opacity: 0; }
  50% { opacity: 0.8; }
  100% { transform: translateY(-200px) scale(1.5); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;display:flex;justify-content:center;align-items:center;';

const colors = ['#ff0000', '#ff7f00', '#ffff00', '#00ff00', '#0000ff', '#4b0082', '#9400d3'];

colors.forEach((color, index) => {
  const orb = document.createElement('div');
  orb.className = 'chakra-orb';
  orb.style.background = color;
  orb.style.boxShadow = `0 0 20px ${color}`;
  orb.style.animationDelay = `${index * 0.8}s`;
  c.appendChild(orb);
});
